@Entity
@Table(name = "claim_sequence")
public class ClaimSequence {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "prefix", nullable = false)
