333	        if (claim.getStatus() != ClaimStatus.SETTLED) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT,
335	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
336	        }
337	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
