356	     *  loses any figure a statement bound it to (it is live again until its new person's next statement), and is
357	     *  listed as its new person's newest claim. Refused for a role the permission matrix does not allow (by default a clerk), for a SETTLED or VOID claim, for a move to the
358	     *  person it is already of, for one dated inside a closed period or after the new person retired, and for a
359	     *  correction the new person has no SETTLED claim of that number for. */
360	    @Transactional
361	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
362	        sheets.load(sheetId, user);
363	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
364	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
365	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
366	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
367	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
368	        if (!sheet.allows("reassign", roles.roleOf(sheetId, user))) {
369	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
370	        }
371	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
372	            throw new ResponseStatusException(HttpStatus.CONFLICT,
373	                    "A " + claim.getStatus() + " claim cannot be reassigned");
