381	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
382	        Rollup.Figures before = rollup.of(sheetId);
383	        claim.unbind();
384	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
385	        Claim moved = claims.saveAndFlush(claim);
386	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
387	                + " from=" + from.getName() + " to=" + to.getName());
388	        rollup.recordChanges(sheetId, user, before);
389	        return moved;
390	    }
