397	     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
398	     *  and note, the next number, opened by this user, a due-by fixed now from the terms in force on the date and
399	     *  naming the original as the claim it was split from, is listed as the person's newest. Refused for a claim
400	     *  that is not OPEN or is deferred, one dated inside a closed period, an amount out of range, and a role the
401	     *  permission matrix does not allow to open a claim. */
402	    @Transactional
403	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
404	        sheets.load(sheetId, user);
405	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
406	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
407	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
408	        refuseIfClosed(sheetId, claim.getDate());
409	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
410	            throw new ResponseStatusException(HttpStatus.CONFLICT,
411	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one not deferred can");
412	        }
413	        if (!sheet.allows("open", roles.roleOf(sheetId, user))) {
414	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
415	        }
416	        BigDecimal part = scaled(amount);
417	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
418	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
419	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
420	        }
421	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
422	        Rollup.Figures before = rollup.of(sheetId);
423	        claim.setAmount(claim.getAmount().subtract(part));
424	        claim.unbind();
425	        Claim original = claims.saveAndFlush(claim);
426	        LocalDate date = original.getDate();
427	        LocalDate dueBy = date.plusDays(termsOf(sheet, person, date));
428	        Claim added = new Claim(sheetId, person.getId(), part, date, dueBy, original.getNote(), null,
429	                claims.lastListed(sheetId) + 1);
430	        added.openAsSplit(nextNumber(sheet, date), user, original.getNumber());
431	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
432	        added = claims.saveAndFlush(added);
433	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
434	                + " into=" + added.getNumber());
435	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
436	        rollup.recordChanges(sheetId, user, before);
437	        return new Split(original, added);
438	    }
439	
440	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
441	     *  dated inside a closed period. */
442	    private Claim pendingClaim(String sheetId, String user, long id) {
443	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
444	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
445	        refuseIfClosed(sheetId, claim.getDate());
446	        if (claim.getStatus() != ClaimStatus.PENDING) {
447	            throw new ResponseStatusException(HttpStatus.CONFLICT,
448	                    "A " + claim.getStatus() + " claim is not waiting for approval");
449	        }
450	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
451	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
452	        }
453	        return claim;
454	    }
455	
456	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
457	     *  gained on top, raised to the floor in force on its date; null when it has no figure. */
458	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
459	        BigDecimal live = liveNow(sheet, claim, person);
460	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained,
461	        // raised to the floor.
462	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
463	        return figure == null ? null : floored(claim, figure.add(lateCharge(claim, figure, sheet)), sheet);
464	    }
465	
466	    /** A claim's live figure as rates and grades are now, bound by no statement; null when its grade has
467	     *  no rate in force on its date. */
468	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
469	        String sheetId = sheet.getId();
470	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
471	                .map(Rate::getRate)
472	                .map(rate -> liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
473	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
474	                .orElse(null);
475	    }
476	
477	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
478	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
479	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
480	    }
481	
482	    private static String dueText(Claim claim) {
483	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
484	    }
485	
486	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
487	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
488	    private String nextNumber(Sheet sheet, LocalDate date) {
489	        if (!sheet.numbersPerPeriod()) {
490	            return String.valueOf(sheet.nextClaimNumber());
491	        }
492	        String prefix = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
493	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
494	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
495	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
496	        String number = sequence.next();
497	        sequences.save(sequence);
498	        return number;
499	    }
500	
501	    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
502	     *  date (a claim with no due, or on a sheet with no threshold then, needs none). */
503	    private static void refuseUnproven(Sheet sheet, Claim claim, BigDecimal due) {
504	        BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
505	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
506	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
507	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
508	        }
509	    }
510	
511	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
512	     *  clerk limit (a claim with no due is within any limit). */
513	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
514	        BigDecimal limit = sheet.getClerkLimit();
515	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
516	            return false;
517	        }
518	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
519	    }
520	
521	    /** Refuse to void a SETTLED claim for anyone but a steward, and on a sheet's today more than
522	     *  {@value #SETTLED_VOID_DAYS} days after (or before) the day its log records it settled. */
523	    private void refuseSettledVoid(Sheet sheet, String user, Claim claim) {
524	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
525	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
526	        }
527	        LocalDate settled = claim.settledOn();
528	        LocalDate today = sheet.getToday();
529	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
530	            throw new ResponseStatusException(HttpStatus.CONFLICT,
531	                    "A SETTLED claim can be voided only within " + SETTLED_VOID_DAYS + " days of its settlement");
532	        }
533	    }
534	
535	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
536	     *  and a claim that is not a correction but names one. */
537	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
538	        if (amount.signum() >= 0) {
539	            if (corrects != null) {
540	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
541	                        "Only a correction (a negative amount) names a claim it corrects");
542	            }
543	            return;
544	        }
545	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
546	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
547	        if (!settled) {
548	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
549	                    "A correction must name the number of a SETTLED claim of the same person");
550	        }
551	    }
552	
553	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
554	    private void refuseIfClosed(String sheetId, LocalDate date) {
555	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
556	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
557	        }
558	    }
559	
560	    /** Refuse a claim dated after its person's retirement date. */
561	    private static void refuseIfRetired(Person person, LocalDate date) {
562	        if (person.refusesClaimOn(date)) {
563	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
564	                    "That claim is dated after " + person.getName() + " retired");
565	        }
566	    }
567	
568	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
569	    private static String entry(String event, String user, Person person, Claim claim, String number) {
570	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
571	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
572	                + (number == null ? "" : " number=" + number);
573	    }
574	
575	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
576	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
577	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
578	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
579	    }
580	
581	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
582	     *  claim of the same person it corrects. */
583	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
584	        if (claim.getCorrects() == null) {
585	            return claim.getDate();
586	        }
587	        return sheetClaims.stream()
588	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
589	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
590	    }
591	
592	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
593	     *  full 30 days past the day it is due by, the late percent in force on that boundary date (its due-by plus 30, 60,
594	     *  90 ... days) of the figure, rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, or
595	     *  it is a correction. */
596	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
597	        BigDecimal none = BigDecimal.ZERO.setScale(2);
598	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
599	            return none;
600	        }
601	        return lateChargeAsOpen(claim, figure, sheet);
602	    }
603	
604	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
605	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
606	        BigDecimal none = BigDecimal.ZERO.setScale(2);
607	        if (figure == null || claim.isCorrection()) {
608	            return none;
609	        }
610	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
611	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
612	        BigDecimal charge = none;
613	        for (long k = 1; k <= periods; k++) {
614	            charge = charge.add(dueOn(figure, sheet.latePctOn(claim.getDueBy().plusDays(30 * k)), rounding));
615	        }
616	        return charge;
617	    }
618	
619	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds. The floor is not applied
620	     *  to it: it is applied last, to the figure with its late charge (see {@link #floored(Claim, BigDecimal, Sheet)}). */
621	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, RoundingMode rounding) {
622	        return dueOn(claim.getAmount(), rate, rounding);
623	    }
624	
625	    /** A claim's due (its figure with its late charge) raised to the floor in force on its date, unless it is a
626	     *  correction. */
627	    public static BigDecimal floored(Claim claim, BigDecimal due, Sheet sheet) {
628	        return due == null || claim.isCorrection() || sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
629	    }
630	
631	    /** A live due raised to the sheet's floor when it is below it. */
632	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
633	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
634	    }
635	
636	    /** The terms in days a claim of the person dated {@code date} is due by: the person's own, else their grade's
637	     *  in force then, else the sheet's then. */
638	    private static int termsOf(Sheet sheet, Person person, LocalDate date) {
639	        return person.getTerms() != null ? person.getTerms() : sheet.termsFor(person.gradeOn(date), date);
640	    }
641	
642	    private static BigDecimal scaled(BigDecimal amount) {
643	        return amount.setScale(2, RoundingMode.UNNECESSARY);
644	    }
645	
646	    private static String noteOf(String note) {
647	        return note == null ? "" : note.trim();
648	    }
649	}
